        channels[1] <= 8'd2;
        channels[2] <= 8'd3;
        channels[3] <= 8'd4;
        channels[4] <= 8'd5;
        channels[5] <= 8'd6;
        channels[6] <= 8'd7;
        channels[7] <= 8'd8;
    end else if (start) begin
        data_out <= channels[channel_select]; // Transfer data from selected channel
    end
end

endmodule

